const text = $('Telegram Trigger').first().json.message?.text || $input.first().json.text || '';

const nameMatch = text.match(/Name:\s*(.+)/i);
const notesMatch = text.match(/Notes:\s*([\s\S]+)/i);

if (nameMatch && notesMatch) {
  const rawName = nameMatch[1].trim();
  const nameParts = rawName.split(/\s+/);

  const firstName = nameParts[0] || '';
  const lastName = nameParts.slice(1).join(' ') || '';

  return {
    status: true,
    firstName: firstName,
    lastName: lastName,
    searchNotes: notesMatch[1].trim()
  };
} else {
  return {
    status: false,
    firstName: null,
    lastName: null,
    searchNotes: null
  };
}

